function updateContextProvider(current, workInProgress, renderLanes) {
  const context = providerType._context
  const newValue = newProps.value
  const oldValue = oldProps?.value

  pushProvider(workInProgress, context, newValue)  // Fiber Stack에 push

  if (is(oldValue, newValue)) {
    return bailoutOnAlreadyFinishedWork(...)  // value 안 바뀜 → 서브트리 스킵
  } else {
    propagateContextChange(...)  // value 바뀜 → consumer들에게 알림
  }

  reconcileChildren(...)  // 자식 렌더링 계속
}

