title:
function readContext(context) {
  const value = context._currentValue  // 현재 값 읽기

  // Fiber의 dependencies에 context 등록
  currentlyRenderingFiber.dependencies = {
    lanes: NoLanes,
    firstContext: {
      context: context,
      memoizedValue: value,
      next: null,
    },
  }

  return value
}

